function build_fdir_model(modelName)
% BUILD_FDIR_MODEL  Regenerate FDIR_SensorFault_Subsystem.slx in this release.
%
% The committed model was saved in R2026b and R2026a refuses to load it
% (Simulink:Commands:LoadingNewerModel). Rather than hand-edit the archive,
% this script rebuilds the same structure - FDIR feeding FDIR1, same block
% names - against the fixed logic in the fdir_*.m functions, so the model
% can be regenerated by anyone on the team standard release.
%
% The MATLAB Function blocks are thin wrappers: each one holds its own
% persistent state and calls the matching .m function, so the logic stays
% diffable and the tests can exercise it without Simulink.
%
%   build_fdir_model()            % writes FDIR_SensorFault_Subsystem.slx
%   build_fdir_model(name)        % writes <name>.slx

if nargin < 1 || isempty(modelName)
    modelName = 'FDIR_SensorFault_Subsystem';
end

here = fileparts(mfilename('fullpath'));
addpath(here);

Init_FDIR;
C = fdir_config();
NUM_FAULTS = C.NUM_FAULTS;
NUM_CHECKS = C.N_SENSORS * C.N_CHECKS;

if bdIsLoaded(modelName)
    close_system(modelName, 0);
end
new_system(modelName);
load_system(modelName);

% ---- Solver: discrete, fixed step at the FDIR frame rate ----
set_param(modelName, 'SolverType', 'Fixed-step', 'Solver', 'FixedStepDiscrete', ...
    'FixedStep', num2str(C.SAMPLE_RATE_SEC), 'StopTime', '0.1', ...
    'SaveFormat', 'Dataset', 'SignalLogging', 'on');

%% ---------------- Root level ----------------
% Every input the subsystems need comes from a named From Workspace block so
% the tests can drive it.
addFromWs(modelName, 'Sensor_data',          'Sensor_data',          [40, 40, 150, 70], C);
addFromWs(modelName, 'fdir_source_mask',     'fdir_source_mask',     [40, 100, 150, 130], C);
addFromWs(modelName, 'fdir_ground_reset',    'fdir_ground_reset',    [40, 160, 150, 190], C);
addFromWs(modelName, 'fdir_ekf_ref',         'fdir_ekf_ref',         [40, 220, 150, 250], C);
addFromWs(modelName, 'fdir_flight_state',    'fdir_flight_state',    [40, 300, 150, 330], C);
addFromWs(modelName, 'fdir_ground_override', 'fdir_ground_override', [40, 360, 150, 390], C);

% Mask / ground reset / EKF reference are bundled into the FDIR In1 port,
% matching the Demux1 that was already inside FDIR.
add_block('simulink/Signal Routing/Mux', [modelName '/Mux'], ...
    'Inputs', '3', 'Position', [210, 95, 215, 255]);
add_line(modelName, 'fdir_source_mask/1',  'Mux/1', 'autorouting', 'on');
add_line(modelName, 'fdir_ground_reset/1', 'Mux/2', 'autorouting', 'on');
add_line(modelName, 'fdir_ekf_ref/1',      'Mux/3', 'autorouting', 'on');

add_block('built-in/SubSystem', [modelName '/FDIR'],  'Position', [300, 40, 440, 200]);
add_block('built-in/SubSystem', [modelName '/FDIR1'], 'Position', [540, 40, 700, 220]);

%% ---------------- FDIR: the four sensor monitors ----------------
fdir = [modelName '/FDIR'];
delete_line_if_any(fdir);
delete_default_io(fdir);

add_block('built-in/Inport',  [fdir '/Sensor_data'], 'Port', '1', 'Position', [30, 60, 60, 74]);
add_block('built-in/Inport',  [fdir '/In1'],         'Port', '2', 'Position', [30, 300, 60, 314]);

% Sensor_data and fdir_ekf_ref share the same 11-wide stacked layout:
% IMU(6), Barometer(1), Lidar(1), GPS(3).
sensorSplit = '[6 1 1 3]';
add_block('simulink/Signal Routing/Demux', [fdir '/Demux'], ...
    'Outputs', sensorSplit, 'Position', [120, 40, 125, 200]);
add_block('simulink/Signal Routing/Demux', [fdir '/Demux1'], ...
    'Outputs', '[4 1 11]', 'Position', [120, 280, 125, 400]);
add_block('simulink/Signal Routing/Demux', [fdir '/Demux2'], ...
    'Outputs', '4', 'Position', [200, 280, 205, 360]);
add_block('simulink/Signal Routing/Demux', [fdir '/Demux3'], ...
    'Outputs', sensorSplit, 'Position', [200, 400, 205, 520]);

add_line(fdir, 'Sensor_data/1', 'Demux/1', 'autorouting', 'on');
add_line(fdir, 'In1/1', 'Demux1/1', 'autorouting', 'on');
add_line(fdir, 'Demux1/1', 'Demux2/1', 'autorouting', 'on');
add_line(fdir, 'Demux1/3', 'Demux3/1', 'autorouting', 'on');

sensors   = {'IMU', 'Barometer', 'Lidar', 'GPS'};
subNames  = {'Subsystem', 'Subsystem1', 'Subsystem2', 'Subsystem3'};
nChannels = [6, 1, 1, 3];

for k = 1:4
    sub = [fdir '/' subNames{k}];
    add_block('built-in/SubSystem', sub, 'Position', [300, 40 + 150*(k-1), 480, 160 + 150*(k-1)]);
    delete_default_io(sub);

    add_block('built-in/Inport', [sub '/' sensors{k} '_data'], 'Port', '1', 'Position', [30, 40, 60, 54]);
    add_block('built-in/Inport', [sub '/Source_Mask'],         'Port', '2', 'Position', [30, 90, 60, 104]);
    add_block('built-in/Inport', [sub '/ground_reset'],        'Port', '3', 'Position', [30, 140, 60, 154]);
    add_block('built-in/Inport', [sub '/ekf_result'],          'Port', '4', 'Position', [30, 190, 60, 204]);

    addMatlabFcn(sub, 'MATLAB Function', monitorCode(sensors{k}, nChannels(k)), [160, 30, 330, 215]);

    add_block('built-in/Outport', [sub '/raw_fail'],      'Port', '1', 'Position', [420, 60, 450, 74]);
    add_block('built-in/Outport', [sub '/monitor_valid'], 'Port', '2', 'Position', [420, 110, 450, 124]);
    add_block('built-in/Outport', [sub '/Meas_Bus'],      'Port', '3', 'Position', [420, 160, 450, 174]);

    add_line(sub, [sensors{k} '_data/1'], 'MATLAB Function/1', 'autorouting', 'on');
    add_line(sub, 'Source_Mask/1',        'MATLAB Function/2', 'autorouting', 'on');
    add_line(sub, 'ground_reset/1',       'MATLAB Function/3', 'autorouting', 'on');
    add_line(sub, 'ekf_result/1',         'MATLAB Function/4', 'autorouting', 'on');
    add_line(sub, 'MATLAB Function/1', 'raw_fail/1',      'autorouting', 'on');
    add_line(sub, 'MATLAB Function/2', 'monitor_valid/1', 'autorouting', 'on');
    add_line(sub, 'MATLAB Function/3', 'Meas_Bus/1',      'autorouting', 'on');

    add_line(fdir, sprintf('Demux/%d', k),  sprintf('%s/1', subNames{k}), 'autorouting', 'on');
    add_line(fdir, sprintf('Demux2/%d', k), sprintf('%s/2', subNames{k}), 'autorouting', 'on');
    add_line(fdir, 'Demux1/2',              sprintf('%s/3', subNames{k}), 'autorouting', 'on');
    add_line(fdir, sprintf('Demux3/%d', k), sprintf('%s/4', subNames{k}), 'autorouting', 'on');
end

add_block('simulink/Math Operations/Vector Concatenate', [fdir '/Vector' newline 'Concatenate'], ...
    'NumInputs', '4', 'Position', [560, 60, 565, 160]);
add_block('simulink/Math Operations/Vector Concatenate', [fdir '/Vector' newline 'Concatenate1'], ...
    'NumInputs', '4', 'Position', [560, 220, 565, 320]);

for k = 1:4
    add_line(fdir, sprintf('%s/1', subNames{k}), sprintf('Vector\nConcatenate/%d', k), 'autorouting', 'on');
    add_line(fdir, sprintf('%s/2', subNames{k}), sprintf('Vector\nConcatenate1/%d', k), 'autorouting', 'on');
end

add_block('built-in/Outport', [fdir '/raw_fail'],           'Port', '1', 'Position', [650, 100, 680, 114]);
add_block('built-in/Outport', [fdir '/monitor_valid'],      'Port', '2', 'Position', [650, 260, 680, 274]);
add_block('built-in/Outport', [fdir '/IMU_feedback'],       'Port', '3', 'Position', [650, 340, 680, 354]);
add_block('built-in/Outport', [fdir '/Barometer_feedback'], 'Port', '4', 'Position', [650, 390, 680, 404]);
add_block('built-in/Outport', [fdir '/Lidar_feedback'],     'Port', '5', 'Position', [650, 440, 680, 454]);
add_block('built-in/Outport', [fdir '/GPS_feedback'],       'Port', '6', 'Position', [650, 490, 680, 504]);

add_line(fdir, sprintf('Vector\nConcatenate/1'),  'raw_fail/1',      'autorouting', 'on');
add_line(fdir, sprintf('Vector\nConcatenate1/1'), 'monitor_valid/1', 'autorouting', 'on');
feedbacks = {'IMU_feedback', 'Barometer_feedback', 'Lidar_feedback', 'GPS_feedback'};
for k = 1:4
    add_line(fdir, sprintf('%s/3', subNames{k}), [feedbacks{k} '/1'], 'autorouting', 'on');
end

%% ---------------- FDIR1: persistence, arbitration, response ----------------
fdir1 = [modelName '/FDIR1'];
delete_default_io(fdir1);

add_block('built-in/Inport', [fdir1 '/raw_fails'],       'Port', '1', 'Position', [30, 60, 60, 74]);
add_block('built-in/Inport', [fdir1 '/flight_state'],    'Port', '2', 'Position', [30, 130, 60, 144]);
add_block('built-in/Inport', [fdir1 '/ground_reset'],    'Port', '3', 'Position', [30, 200, 60, 214]);
add_block('built-in/Inport', [fdir1 '/ground_override'], 'Port', '4', 'Position', [30, 270, 60, 284]);

% Persistence runs over the 16 monitor checks, because checks that share a
% catalog row do not share a threshold.
addMatlabFcn(fdir1, 'FDIR_Persistence', persistenceCode(NUM_CHECKS), [160, 40, 340, 230]);
add_line(fdir1, 'raw_fails/1',    'FDIR_Persistence/1', 'autorouting', 'on');
add_line(fdir1, 'ground_reset/1', 'FDIR_Persistence/2', 'autorouting', 'on');
add_line(fdir1, 'flight_state/1', 'FDIR_Persistence/3', 'autorouting', 'on');

% Arbitration runs over the 102 catalog rows, because that is where
% Response_Tier lives, so the latched checks fold onto their rows.
addMatlabFcn(fdir1, 'Fault_Map_Fold', foldCode(NUM_CHECKS, NUM_FAULTS), [400, 45, 550, 130]);
add_line(fdir1, 'FDIR_Persistence/1', 'Fault_Map_Fold/1', 'autorouting', 'on');

% Nothing in this subsystem acknowledges a response yet, so the feedback bus
% is driven with its default value until a responder is wired in.
add_block('simulink/Sources/Constant', [fdir1 '/Response_Feedback'], ...
    'Value', 'struct(''Response_Ack'', false, ''Execution_Status'', uint8(0))', ...
    'OutDataTypeStr', 'Bus: Response_Feedback_Bus', ...
    'Position', [340, 300, 470, 330]);

addMatlabFcn(fdir1, 'FDIR_Arbtration', arbitrationCode(), [620, 40, 800, 230]);
add_line(fdir1, 'Fault_Map_Fold/1',    'FDIR_Arbtration/1', 'autorouting', 'on');
add_line(fdir1, 'flight_state/1',      'FDIR_Arbtration/2', 'autorouting', 'on');
add_line(fdir1, 'ground_override/1',   'FDIR_Arbtration/3', 'autorouting', 'on');
add_line(fdir1, 'Response_Feedback/1', 'FDIR_Arbtration/4', 'autorouting', 'on');

addMatlabFcn(fdir1, 'Response_Mapping', responseCode(), [860, 40, 1040, 260]);
add_line(fdir1, 'FDIR_Arbtration/1', 'Response_Mapping/1', 'autorouting', 'on');

outNames = {'fail_counts', 'Mask_Target', 'Degrade_Multiplier', 'Abort_Land_Active', ...
            'Nav_Fallback_Active', 'Cutoff_Active', 'Entry_Trigger'};
for k = 1:numel(outNames)
    add_block('built-in/Outport', [fdir1 '/' outNames{k}], 'Port', num2str(k), ...
        'Position', [1120, 40 + 50*(k-1), 1150, 54 + 50*(k-1)]);
end
add_line(fdir1, 'FDIR_Persistence/2', 'fail_counts/1', 'autorouting', 'on');
for k = 2:numel(outNames)
    add_line(fdir1, sprintf('Response_Mapping/%d', k-1), [outNames{k} '/1'], 'autorouting', 'on');
end

%% ---------------- Root wiring ----------------
add_line(modelName, 'Sensor_data/1', 'FDIR/1', 'autorouting', 'on');
add_line(modelName, 'Mux/1',         'FDIR/2', 'autorouting', 'on');
add_line(modelName, 'FDIR/1',                 'FDIR1/1', 'autorouting', 'on');
add_line(modelName, 'fdir_flight_state/1',    'FDIR1/2', 'autorouting', 'on');
add_line(modelName, 'fdir_ground_reset/1',    'FDIR1/3', 'autorouting', 'on');
add_line(modelName, 'fdir_ground_override/1', 'FDIR1/4', 'autorouting', 'on');

% Logging sinks, so FDIR_Tests can read the response out of a sim run.
logs = { ...
    'FDIR/1',  'fdir_log_raw_fail'; ...
    'FDIR/2',  'fdir_log_monitor_valid'; ...
    'FDIR1/1', 'fdir_log_fail_counts'; ...
    'FDIR1/2', 'fdir_log_mask_target'; ...
    'FDIR1/3', 'fdir_log_degrade'; ...
    'FDIR1/4', 'fdir_log_abort_land'; ...
    'FDIR1/5', 'fdir_log_nav_fallback'; ...
    'FDIR1/6', 'fdir_log_cutoff'; ...
    'FDIR1/7', 'fdir_log_entry_trigger'};
for k = 1:size(logs, 1)
    blk = [modelName '/' logs{k, 2}];
    add_block('simulink/Sinks/To Workspace', blk, 'VariableName', logs{k, 2}, ...
        'SaveFormat', 'Timeseries', 'Position', [880, 40 + 50*(k-1), 1000, 70 + 50*(k-1)]);
    add_line(modelName, logs{k, 1}, [logs{k, 2} '/1'], 'autorouting', 'on');
end

% The per-sensor measurement feedback ports have no consumer at this level.
for k = 3:6
    blk = sprintf('%s/Terminator%d', modelName, k);
    add_block('simulink/Sinks/Terminator', blk, 'Position', [880, 500 + 40*k, 900, 520 + 40*k]);
    add_line(modelName, sprintf('FDIR/%d', k), sprintf('Terminator%d/1', k), 'autorouting', 'on');
end

%% ---------------- Bus types on the MATLAB Function ports ----------------
setPortType(modelName, 'FDIR1/FDIR_Persistence', 'states', ...
    'Bus: Fault_State_Bus', num2str(NUM_CHECKS));
setPortType(modelName, 'FDIR1/Fault_Map_Fold', 'check_states', ...
    'Bus: Fault_State_Bus', num2str(NUM_CHECKS));
setPortType(modelName, 'FDIR1/Fault_Map_Fold', 'fault_states', ...
    'Bus: Fault_State_Bus', num2str(NUM_FAULTS));
setPortType(modelName, 'FDIR1/FDIR_Arbtration', 'fault_states', ...
    'Bus: Fault_State_Bus', num2str(NUM_FAULTS));
setPortType(modelName, 'FDIR1/FDIR_Arbtration', 'response_feedback', ...
    'Bus: Response_Feedback_Bus', '-1');

Simulink.BlockDiagram.arrangeSystem(modelName);
Simulink.BlockDiagram.arrangeSystem(fdir);
Simulink.BlockDiagram.arrangeSystem(fdir1);

save_system(modelName, fullfile(here, [modelName '.slx']));
fprintf('Built %s in %s\n', modelName, version('-release'));
end

%% ======================= helpers =======================

function addFromWs(sys, name, varName, pos, C)
add_block('simulink/Sources/From Workspace', [sys '/' name], ...
    'VariableName', varName, 'SampleTime', num2str(C.SAMPLE_RATE_SEC), ...
    'OutputAfterFinalValue', 'Holding final value', 'Position', pos);
end

function addMatlabFcn(sys, name, code, pos)
blkPath = [sys '/' name];
add_block('simulink/User-Defined Functions/MATLAB Function', blkPath, 'Position', pos);
chart = sfPart(blkPath, 'Stateflow.EMChart');
chart.Script = code;
end

function setPortType(modelName, relPath, dataName, dataType, dims)
chart = sfPart([modelName '/' relPath], 'Stateflow.EMChart');
d = chart.find('-isa', 'Stateflow.Data', '-and', 'Name', dataName);
d(1).DataType = dataType;
if ~strcmp(dims, '-1')
    d(1).Props.Array.Size = dims;
end
end

function part = sfPart(blkPath, isa)
root = sfroot;
part = root.find('-isa', isa, '-and', 'Path', blkPath);
part = part(1);
end

function delete_default_io(sys)
% A fresh SubSystem ships with In1 -> Out1; clear it before building.
lines = find_system(sys, 'SearchDepth', 1, 'FindAll', 'on', 'Type', 'line');
for i = 1:numel(lines)
    delete_line(lines(i));
end
for blk = {'In1', 'Out1'}
    p = [sys '/' blk{1}];
    if getSimulinkBlockHandle(p) > 0
        delete_block(p);
    end
end
end

function delete_line_if_any(~)
end

%% ======================= block code =======================

function code = monitorCode(sensorName, nChannels)
code = sprintf([ ...
'function [raw_fail, monitor_valid, Meas_Bus] = fcn(%s_data, Source_Mask, ground_reset, ekf_result)\n' ...
'%%#codegen\n' ...
'%% Thin wrapper - the logic lives in fdir_sensor_monitor.m.\n' ...
'persistent mon_state\n' ...
'if isempty(mon_state)\n' ...
'    mon_state = fdir_monitor_state(%d);\n' ...
'end\n' ...
'C = fdir_config();\n' ...
'[raw_fail, monitor_valid, Meas_Bus, mon_state] = fdir_sensor_monitor( ...\n' ...
'    %s_data, ekf_result, Source_Mask, ground_reset, C.sensors.%s, mon_state);\n' ...
'end\n'], sensorName, nChannels, sensorName, sensorName);
end

function code = foldCode(numChecks, numFaults)
code = sprintf([ ...
'function fault_states = fcn(check_states)\n' ...
'%%#codegen\n' ...
'%% Thin wrapper - the logic lives in fdir_fold_checks.m.\n' ...
'%% %d latched monitor checks -> %d catalog-indexed fault states.\n' ...
'C = fdir_config();\n' ...
'fault_states = fdir_fold_checks(check_states, C.fault_map, %d);\n' ...
'end\n'], numChecks, numFaults, numFaults);
end

function code = persistenceCode(numChecks)
code = sprintf([ ...
'function [states, fail_counts] = fcn(raw_fails, ground_reset, flight_state)\n' ...
'%%#codegen\n' ...
'%% Thin wrapper - the logic lives in fdir_persistence.m.\n' ...
'persistent p_state\n' ...
'[C, ~, ~, check_config] = fdir_config();\n' ...
'if isempty(p_state)\n' ...
'    p_state = fdir_persistence_state(%d, C.M_WINDOW_SIZE);\n' ...
'end\n' ...
'%% The ground reset command is a single discrete, applied to every check.\n' ...
'ground_resets = repmat(logical(ground_reset), %d, 1);\n' ...
'[states, fail_counts, p_state] = fdir_persistence( ...\n' ...
'    raw_fails, ground_resets, flight_state, check_config, p_state);\n' ...
'end\n'], numChecks, numChecks);
end

function code = arbitrationCode()
code = [ ...
'function active_response = fcn(fault_states, flight_state, Ground_override, response_feedback)' newline ...
'%#codegen' newline ...
'% Thin wrapper - the logic lives in fdir_arbitration.m.' newline ...
'persistent current_response' newline ...
'if isempty(current_response)' newline ...
'    current_response = uint8(0); % R0 (Nominal)' newline ...
'end' newline ...
'[~, fault_config] = fdir_config();' newline ...
'[active_response, current_response] = fdir_arbitration( ...' newline ...
'    fault_states, flight_state, Ground_override, response_feedback, ...' newline ...
'    fault_config, current_response);' newline ...
'end' newline];
end

function code = responseCode()
code = [ ...
'function [Mask_Target, Degrade_Multiplier, Abort_Land_Active, Nav_Fallback_Active, Cutoff_Active, Entry_Trigger] = fcn(active_response)' newline ...
'%#codegen' newline ...
'% Thin wrapper - the logic lives in fdir_response_mapping.m.' newline ...
'[Mask_Target, Degrade_Multiplier, Abort_Land_Active, Nav_Fallback_Active, Cutoff_Active, Entry_Trigger] = ...' newline ...
'    fdir_response_mapping(active_response);' newline ...
'end' newline];
end
